std::pair<
  common::optional<
    std::shared_ptr<types::IElement>
  >,
  common::optional<DeserializationError>
> DeserializeElement(
  const nlohmann::json& json,
  bool additional_properties
) {
  const std::string* model_type_str;
  common::optional<DeserializationError> error;

  std::tie(
    model_type_str,
    error
  ) = GetModelTypeFrom(json);

  if (error.has_value()) {
    return NoInstanceAndDeserializationError<
      std::shared_ptr<types::IElement>
    >(
      std::move(*error)
    );
  }

  common::optional<types::ModelType> model_type(
    ModelTypeFromModelTypeString(*model_type_str)
  );

  if (!model_type.has_value()) {
    return NoInstanceAndDeserializationErrorWithCause<
      std::shared_ptr<types::IElement>
    >(
      common::Concat(
        L"The model type does not correspond to any known class: ",
        common::Utf8ToWstring(*model_type_str)
      )
    );
  }

  switch (*model_type) {
    case types::ModelType::kLeaf:
      return ParsePropertiesOfLeaf<
        types::IElement
      >(json, additional_properties);
    case types::ModelType::kOrderedContainer:
      return ParsePropertiesOfOrderedContainer<
        types::IElement
      >(json, additional_properties);
    case types::ModelType::kUnorderedContainer:
      return ParsePropertiesOfUnorderedContainer<
        types::IElement
      >(json, additional_properties);
    default:
      return NoInstanceAndDeserializationErrorWithCause<
        std::shared_ptr<types::IElement>
      >(
        common::Concat(
          L"The dispatch to the JSON de-serialization of "
          L"types::IElement "
          L"is not defined for model type: ",
          common::Utf8ToWstring(*model_type_str)
        )
      );
  }
}

template <
  typename T,
  typename std::enable_if<
    std::is_base_of<T, types::ILeaf>::value
  >::type*
>
std::pair<
  common::optional<std::shared_ptr<T> >,
  common::optional<DeserializationError>
> ParsePropertiesOfLeaf(
  const nlohmann::json& json,
  bool additional_properties
) {
  common::optional<std::wstring> the_identifier;

  common::optional<std::wstring> the_text;

  common::optional<DeserializationError> error(
    ParseProperties(
      json,
      properties::kMapOfLeaf,
      additional_properties,
      [&](
        properties::OfLeaf property,
        const nlohmann::json& value
      ) -> common::optional<DeserializationError> {
        switch (property) {
          case properties::OfLeaf::kIdentifier:
            return ParseInto(
              the_identifier,
              DeserializeWstring(value)
            );
          case properties::OfLeaf::kText:
            return ParseInto(
              the_text,
              DeserializeWstring(value)
            );
          case properties::OfLeaf::kModelType:
            // NOTE (mristin):
            // The model type has been verified before the loop, so there is nothing
            // left to do with it here.
            return common::nullopt;
          default:
            throw UnexpectedPropertyLiteralError(
              "properties::OfLeaf",
              property
            );
        }
      }
    )
  );

  if (error.has_value()) {
    return NoInstanceAndDeserializationError<
      std::shared_ptr<T>
    >(
      std::move(*error)
    );
  }

  if (!the_identifier.has_value()) {
    return NoInstanceAndDeserializationErrorWithCause<
      std::shared_ptr<T>
    >(
      L"The required property identifier is missing"
    );
  }

  if (!the_text.has_value()) {
    return NoInstanceAndDeserializationErrorWithCause<
      std::shared_ptr<T>
    >(
      L"The required property text is missing"
    );
  }

  return std::make_pair(
    common::make_optional<
      std::shared_ptr<T>
    >(
      // NOTE (mristin):
      // We deliberately do not use std::make_shared here to avoid an unnecessary
      // upcast.
      new types::Leaf(
        std::move(*the_identifier),
        std::move(*the_text)
      )
    ),
    common::nullopt
  );
}

template <
  typename T,
  typename std::enable_if<
    std::is_base_of<T, types::ILeaf>::value
  >::type*
>
std::pair<
  common::optional<std::shared_ptr<T> >,
  common::optional<DeserializationError>
> DeserializeLeaf(
  const nlohmann::json& json,
  bool additional_properties
) {
  common::optional<DeserializationError> error(
    CheckModelType(
      json,
      "Leaf"
    )
  );

  if (error.has_value()) {
    return NoInstanceAndDeserializationError<
      std::shared_ptr<T>
    >(
      std::move(*error)
    );
  }

  return ParsePropertiesOfLeaf<T>(
    json,
    additional_properties
  );
}

