std::pair<
  common::optional<types::AttributeItem>,
  common::optional<DeserializationError>
> DeserializeAttributeItem(
  const nlohmann::json& json,
  bool additional_properties
) {
  common::optional<DeserializationError> not_an_object(
    CheckJsonObject(json)
  );

  if (not_an_object.has_value()) {
    return NoInstanceAndDeserializationError<
      types::AttributeItem
    >(
      std::move(*not_an_object)
    );
  }

  if (json.contains("modelType")) {
    const std::string* model_type_str;
    common::optional<DeserializationError> error;

    std::tie(
      model_type_str,
      error
    ) = GetModelTypeFrom(json);

    if (error.has_value()) {
      return std::make_pair<
        common::optional<types::AttributeItem>,
        common::optional<DeserializationError>
      >(
        common::nullopt,
        std::move(error)
      );
    }

    common::optional<types::ModelType> model_type(
      ModelTypeFromModelTypeString(*model_type_str)
    );

    if (!model_type.has_value()) {
      std::wstring message = common::Concat(
        L"The model type does not correspond to any known class: ",
        common::Utf8ToWstring(*model_type_str)
      );

      return std::make_pair<
        common::optional<types::AttributeItem>,
        common::optional<DeserializationError>
      >(
        common::nullopt,
        common::make_optional<DeserializationError>(
          message
        )
      );
    }

    switch (*model_type) {
      case types::ModelType::kGlobalAttribute: {
        return WrapDeserializedAsVariant<
          types::AttributeItem,
          0
        >(
          ParsePropertiesOfGlobalAttribute(
            json,
            additional_properties
          )
        );
      }
      case types::ModelType::kLocalAttribute: {
        return WrapDeserializedAsVariant<
          types::AttributeItem,
          1
        >(
          ParsePropertiesOfLocalAttribute(
            json,
            additional_properties
          )
        );
      }
      default: {
        std::wstring message = common::Concat(
          L"The dispatch to the JSON de-serialization of "
          L"types::AttributeItem "
          L"is not defined for model type: ",
          common::Utf8ToWstring(*model_type_str)
        );

        return std::make_pair<
          common::optional<types::AttributeItem>,
          common::optional<DeserializationError>
        >(
          common::nullopt,
          common::make_optional<DeserializationError>(
            message
          )
        );
      }
    }
  }

  std::wstring message(
    L"Could not determine a concrete type to dispatch the JSON "
    L"de-serialization of types::AttributeItem to, based neither "
    L"on the modelType nor on the required properties present "
    L"in the object"
  );

  return std::make_pair<
    common::optional<types::AttributeItem>,
    common::optional<DeserializationError>
  >(
    common::nullopt,
    common::make_optional<DeserializationError>(
      message
    )
  );
}

std::pair<
  common::optional<types::StringValue>,
  common::optional<DeserializationError>
> DeserializeStringValue(
  const nlohmann::json& json,
  bool additional_properties
) {
  common::optional<DeserializationError> not_an_object(
    CheckJsonObject(json)
  );

  if (not_an_object.has_value()) {
    return NoInstanceAndDeserializationError<
      types::StringValue
    >(
      std::move(*not_an_object)
    );
  }

  if (json.contains("modelType")) {
    const std::string* model_type_str;
    common::optional<DeserializationError> error;

    std::tie(
      model_type_str,
      error
    ) = GetModelTypeFrom(json);

    if (error.has_value()) {
      return std::make_pair<
        common::optional<types::StringValue>,
        common::optional<DeserializationError>
      >(
        common::nullopt,
        std::move(error)
      );
    }

    common::optional<types::ModelType> model_type(
      ModelTypeFromModelTypeString(*model_type_str)
    );

    if (!model_type.has_value()) {
      std::wstring message = common::Concat(
        L"The model type does not correspond to any known class: ",
        common::Utf8ToWstring(*model_type_str)
      );

      return std::make_pair<
        common::optional<types::StringValue>,
        common::optional<DeserializationError>
      >(
        common::nullopt,
        common::make_optional<DeserializationError>(
          message
        )
      );
    }

    switch (*model_type) {
      case types::ModelType::kStringLiteral: {
        return WrapDeserializedAsVariant<
          types::StringValue,
          0
        >(
          ParsePropertiesOfStringLiteral(
            json,
            additional_properties
          )
        );
      }
      case types::ModelType::kAttributeOperand: {
        return WrapDeserializedAsVariant<
          types::StringValue,
          1
        >(
          ParsePropertiesOfAttributeOperand(
            json,
            additional_properties
          )
        );
      }
      default: {
        std::wstring message = common::Concat(
          L"The dispatch to the JSON de-serialization of "
          L"types::StringValue "
          L"is not defined for model type: ",
          common::Utf8ToWstring(*model_type_str)
        );

        return std::make_pair<
          common::optional<types::StringValue>,
          common::optional<DeserializationError>
        >(
          common::nullopt,
          common::make_optional<DeserializationError>(
            message
          )
        );
      }
    }
  }

  std::wstring message(
    L"Could not determine a concrete type to dispatch the JSON "
    L"de-serialization of types::StringValue to, based neither "
    L"on the modelType nor on the required properties present "
    L"in the object"
  );

  return std::make_pair<
    common::optional<types::StringValue>,
    common::optional<DeserializationError>
  >(
    common::nullopt,
    common::make_optional<DeserializationError>(
      message
    )
  );
}

